        Q_TILE * D * sizeof(half) +
        Q_TILE * THREADS * sizeof(float) +
        Q_TILE * N * sizeof(float) +
        2 * Q_TILE * sizeof(float);

    cudaStream_t stream =
        at::cuda::getCurrentCUDAStream(q.device().index()).stream();

    scaled_dot_product_attention_kernel<<<grid, block, shared_bytes, stream>>>(
        reinterpret_cast<const half*>(q.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(k.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(v.data_ptr<at::Half>()),
        reinterpret_cast<half*>(out.data_ptr<at::Half>()),
        B,
        H,
        N,
        D
